def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    templates = []
    for row in grid:
        c = 0
        while c < w:
            while c < w and row[c] == 0:
                c += 1
            start = c
            while c < w and row[c] != 0:
                c += 1
            if c - start > 1:
                templates.append(row[start:c])
    for y in range(h):
        for x in range(w):
            value = grid[y][x]
            if value == 0 or (x > 0 and grid[y][x-1] != 0) or (x+1 < w and grid[y][x+1] != 0):
                continue
            template = next((seq for seq in templates if value in seq), None)
            if template is None:
                continue
            start = x - template.index(value)
            for offset, color in enumerate(template):
                xx = start + offset
                if 0 <= xx < w:
                    out[y][xx] = color
    return out
